static __attribute__((always_inline)) inline int eval_ins_len(struct verifier_state* st)
{
  return (*st).ins_len;
}

static __attribute__((always_inline)) inline unsigned long long eval_ins(struct verifier_state* st, unsigned int idx)
{
  return *((*st).ins + idx);
}

